//! Report account balances from a ledger file.

use std::collections::HashMap;
use std::env;
use std::fs;
use std::process;

/// Parses an unsigned amount with exactly two fraction digits, such as `12.05`, into cents.
fn to_cents(amount: &str) -> Option<i128> {
    let (whole, frac) = amount.split_once('.')?;
    let digits = |s: &str| !s.is_empty() && s.bytes().all(|b| b.is_ascii_digit());
    if !digits(whole) || !digits(frac) || frac.len() != 2 {
        return None;
    }
    Some(whole.parse::<i128>().ok()? * 100 + frac.parse::<i128>().ok()?)
}

fn format_cents(cents: i128) -> String {
    let sign = if cents < 0 { "-" } else { "" };
    let cents = cents.abs();
    format!("{}{}.{:02}", sign, cents / 100, cents % 100)
}

fn main() {
    let path = env::args().nth(1).unwrap_or_else(|| {
        eprintln!("usage: ledger <path>");
        process::exit(2);
    });
    let text = fs::read_to_string(&path).unwrap_or_else(|err| {
        eprintln!("cannot read {path}: {err}");
        process::exit(1);
    });

    let mut lines = text.lines();
    let count: usize = lines
        .next()
        .and_then(|header| header.split_whitespace().nth(1))
        .and_then(|n| n.parse().ok())
        .unwrap_or_else(|| {
            eprintln!("missing or malformed ledger header");
            process::exit(1);
        });

    let mut balances: HashMap<String, i128> = HashMap::new();
    for (index, line) in lines.take(count).enumerate() {
        let k = index + 1;
        let fields: Vec<&str> = line.split_whitespace().collect();
        let [account, kind, amount] = fields[..] else {
            eprintln!("malformed transaction on line {k}");
            process::exit(1);
        };
        let sign = match kind {
            "debit" => -1,
            "credit" => 1,
            _ => {
                println!("ERROR line {k}");
                return;
            }
        };
        let Some(cents) = to_cents(amount) else {
            eprintln!("malformed amount on line {k}: {amount}");
            process::exit(1);
        };
        *balances.entry(account.to_string()).or_insert(0) += sign * cents;
    }

    let mut entries: Vec<(String, i128)> = balances.into_iter().collect();
    entries.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0)));

    let mut total = 0;
    for (account, balance) in &entries {
        println!("{} {}", account, format_cents(*balance));
        total += balance;
    }
    println!("TOTAL {}", format_cents(total));
}

